  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (241::BIGINT, 'Super amable, explica bien y brinda bastante ayuda si se le pregunta, ya sea durante clases o por correo. Por el otro lado, califica justamente, los quizes son fáciles al igual que los exámenes. Es importante estudiarse las guías antes de los labs y terminar las bitácoras cuanto antes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, '4079139867a612c194cd8471ebe1bbec08f1a169d57a291481af13e8b37be8c3'::TEXT, ARRAY[2968]::BIGINT[]),
    (241::BIGINT, 'El profe tiene mucha paciencia y responde con dedicación, es un profe accesible. El curso se presta para aprender un montón, principalmente con los simuladores, pero se ocupa interiorizar los consejos de diseño que el profe enseña.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3ca7bbce7e46a017e2697391784c30bac1777b2f2c3c52b422c5c04401b8739b'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'El curso se pasa solo. Las tareas son sumamente fáciles, los exámenes son una pequeña parte de lo que se vió en clases, los proyectos son sencillos. Realmente este curso con este profe es sumamente sencillo, no hay nada que temer.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '25007e7e3b60adee69f18af8bf5ded20c8b0825628227f6b72c8aedf696ab76c'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'Explicaba enredado, casi no hacía clases presenciales, mandaba tareas difíciles. Pero ahí va el mejor profesor que ha tenido la escuela de mecatrónica. Se le va a extrañar. (Si tiene la oportunidad de matricular con él, dele sin miedo)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-24T00:00:00+00:00'::TIMESTAMPTZ, '68932a6c513c90a154b86bd77ecb9141b23f81c1e7d0852b7e061fa4ddb92e08'::TEXT, ARRAY[3051]::BIGINT[]),
    (241::BIGINT, 'Es un curso dificil pero el profe lo hace llevadero. Sabe explicar y se preocupa por si el estudiante está entendiendo o no. Le recomiendo ir a consulta con él, ayuda mucho'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-18T00:00:00+00:00'::TIMESTAMPTZ, '16e83008e8461190fdc602085f18a743aa0a481eef37a957a02d9193d9ff980b'::TEXT, ARRAY[1262]::BIGINT[]),
    (241::BIGINT, 'El profesor no explica nada claro. Para el 2do examen todos los contenidos que vimos solamente usó una ínfima parte de lo que vimos, en conclusión, no servía para nada ir a clases, pero había que ir porque era de asistencia obligatoria. La verdad deja todo al azar, al típico "Invente Román invente"'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '8ffb5c3de533e16afbb4b91a21c8a173f3e4e642fcaa9adb4f4858db6975489b'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'No lo sentí tan malo como otros compañeros. Y eso que yo no soy autodidacta. Siento que si se toma el tiempo para estudiar mejor el contenido, planear bien las lecciones, y preparar evaluaciones acorde a dichas lecciones, le va a ir mejor el otro semestre'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '72e80eb0fbaf96e2249241cdbe590d658d3100164473da43866d1bab77119613'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'Es buen profe aunque a veces se confunde dando la materia, pero siempre intenta ayudar a los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5658e04ea9ba7d756c1b5151ed56268574611f9eb7e897265de4f98baee2543b'::TEXT, ARRAY[1262]::BIGINT[]),
    (241::BIGINT, 'Muy buen profesor sabe de la materia a veces se confunde en media explicacion pero al final la explica bien, tiene una base datos con bastante ejercicios para uno practicar y su solucion, las tareas son faciles y los examenes lo entra siempre es lo visto en las clases si estudia con tiempo pasa .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'fc61fc8403b87804505aa653e07e3213e86ad59fa7bd020e8bb3dc80e66749d6'::TEXT, ARRAY[1262]::BIGINT[]),
    (241::BIGINT, 'El curso se logra pasar pero por su propia cuenta, el profesor no sabe explicar y hasta, en ocasiones, parece que no sabe del tema. Hace comentarios inapropiados para un profesor, especialmente hacia mujeres.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3d1eb2eae23532a33996ff2a083d483d6adc23995d1d1b99ac297b558b45a4a9'::TEXT, ARRAY[3051, 1835]::BIGINT[]),
    (241::BIGINT, 'si es mujer ya pasó el curso'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f15c0894fc0b0592d222a370f0f8113331cdeda4544fe83f7b04c41c754eab99'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'El profesor no solo no sabe lo que está enseñando, tampoco sabe explicarlo. Como docente, es difícil imaginar algo peor. Tiene criterios de evaluación como "no me convence", por lo que puede bajarle la nota sin justificación. Y si es mujer, prepárese para recibir una invitación a "tomar un cafe"'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, '9de90576467d430efdf210c9a5806bd1fcf31c231762f0144bb4bb3e71b1da62'::TEXT, ARRAY[2974]::BIGINT[]),
    (241::BIGINT, 'Una joya de profe. El curso es duro pero el se esmera en que sea lo menos duro posible. Califica super justo, no te baja un punto sin explicarte por qué. Los exámenes están muy bien hechos y deja muy buen material para estudiar. Explica de forma normal aunque a veces da risa.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'b7996c1cb8110192404c63c3973d4d44f9fa916a96ff0bb4a9f95f616afd25ad'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Es un curso bastante pesado pero es un profe excelente. Es super amable y siempre está dispuesto a aclarar dudas. Es mucha materia la que se tiene que ver según el programa pero él intenta acomodarla lo mejor posible para beneficio del estudiante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bb13a1981bf365d66da1c896209b83341449004903a8372d4c744d3a5769dbff'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Es un excelente profe y muy buena nota. El curso tiene una distribución de temas muy desordenada, por lo que se complica la distribución de las clases también, pero no es culpa del profesor. Las clases de teoría son muy buenas y en las que se dedica a hacer ejercicios, estos son bastante completos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'aaa9f57ad47fd271ff040ca615a20e26ed7f005e81a7d21605b6c72a59b95203'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'El mejor profe para Circuitos, es muy humano con sus estudiantes y da mucha ayuda, el material que brinda es muy bueno y califica de una manera justa.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '26f330c189b3c4a6b861fef11fb461a508ddb1acce018e1958f28f4fef5e69e2'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Este profe me dio los dos cursos, cc y ca, la verdad cc lo explica super bien, en ca aveces deja un poco de desear en las explicaciones, pero nada que usted no pueda ir a aclarar en la hora de consulta. Es cómico y buena nota por lo general.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'fe8c94de54a47dd46abc1dcd12dc0352bc1c9533c1bb022015323cf1686aaca5'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'No importa la materia, si pueden meter con él HAGANLO. Explica super bien y no califica duro (diria que lo justo). Si uno hace los trabajos de fijo pasa sobrado y la verdad se aprende bastante. Da bastante retroalimentación y es muy agradable. Es de los mejores profes del tec.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'ee27725c8f27f63fde5d7086eae7601c87bbfccd765258bc4df99224adb43851'::TEXT, ARRAY[3051]::BIGINT[]),
    (241::BIGINT, 'Es el mejor profe para este curso, si puede llevar con él no dude en hacerlo, su forma de enseñar y calificar son súper humanas, además que siempre esta interesado por el estudiante; no hay otro profe igual la verdad.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9d91f4c7a23f288520bcf809a3239a3f03e01750891e6808b013ec7eca91ff30'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'El mejor profe para el curso de CC, se interesa porque los estudiantes aprendan. La metodología de evaluación es clara.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '977c8f508ca69482c805404d6e8d23ea475ba8607130a94ebb58158ef7d8f117'::TEXT, ARRAY[1257]::BIGINT[]),
    (241::BIGINT, 'Definitivamente el MEJOR profe para el curso. Sus presentaciones son super claras. Al ser un curso complicado, cambia la forma de evaluar para que a los estudiantes les vaya bien. Es un amor en general. Le gusta hacer algunas clases de teoría virtuales. Por favor llévelo con él. 1000/10'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '8154ed72853a27565682a3f81b1107d4a6f06cd6c034412f7fbb4bb62d6a38b5'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'El profe explica super bien y sus clases son entretenidas, amo su metodología para evaluar'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '327953af7408598f5357cfcb8925c3140c7e159be082d9ecd47e4c29c371d1ec'::TEXT, ARRAY[1257]::BIGINT[]),
    (241::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-01-12T00:00:00+00:00'::TIMESTAMPTZ, '1df078c5fd881f6a2aecf43bc995f19adf6a3c881d54b7d1f04b916dffe33b6f'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-26T00:00:00+00:00'::TIMESTAMPTZ, '351f8d1e53340479abb26584609cb36518cabdd7c2366ef2e8689982a6c59a4e'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Muy mal profesor, muchas tareas y quices. Clases muy aburridas y pasa los últimos temas muy rápido.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-12-21T00:00:00+00:00'::TIMESTAMPTZ, '8e0bbec2884d00dbae825398388357a787ef5563c68e1159815441592a34e9bd'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '6533bac685ac9e351d672b003572d05de8965065f0ef378b6fd2f6c3b5a10c8b'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2022-10-11T00:00:00+00:00'::TIMESTAMPTZ, '818b077992bc82030851b3f7be606e5d5d8f643a998e81150b42ae6c46dbfc67'::TEXT, ARRAY[926, 942, 974]::BIGINT[]),
    (241::BIGINT, 'Super buen profe. Toma en cuenta que e un curso dificil y se asegura que uno entienda. La calificación es bastante más balanceada en comparación a otros profes que dan el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'efab92502454a9981d4680cbe2aebd34773bee49add2dbfcd7f2ac6cd197e267'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Es una muy buena persona. Su metodología ayuda mucho, califica suave. Se nota que sabe mucho y sus presentaciones son muy buenas. Responde rápido los correos. Se aprende mucho con él y es muy comprensible con los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'f1e2894e0630ac6b7c7b880e8ddc1be06cc3fd5ad2679d6a463f1ce676e7af4b'::TEXT, ARRAY[926]::BIGINT[]),
    (241::BIGINT, 'Yo llevé CC y CA con el y aprendí un montón, tiene una forma muy original de evaluar que hace que uno pruebe que sabe y no que sea solo si la respuesta esta correcta. Toma el tiempo de hacer práctica y responder preguntas, aunque por eso algunos temas que se usan a futuro no se ven tan profundo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, '03121886a2965771861f8d8aa30d3325e1fc6b2dbbfaf0ccbc715999c93df2c4'::TEXT, ARRAY[1257, 954]::BIGINT[]),
    (241::BIGINT, 'El mejor profe de verdad. Explica bien pero lo más importante es que permite al estudiante recuperar temas que ya se evaluaron y así uno si le pone no pierde el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3eedf6a56eefdd6600b7fbb19d829dd466c138329e9ed14b9e2854d2ff1dbf76'::TEXT, ARRAY[3049]::BIGINT[]),
    (241::BIGINT, 'Super pura vida y entiende bien la situación del estudiantado. Los métodos de calificación son extraños pero fáciles, todo mundo pasa. El problema es que no siento que deje buenas bases para el resto de cursos más adelante. Explica muy claro y es muy accesible en consulta.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a45a1529f373869b1afcee37895fdff07e3205435c65cfe190ffbafbf78bcda5'::TEXT, ARRAY[3049]::BIGINT[]),
